import{_ as r,a0 as s,w as e,s as a,I as n,x as l,a1 as i,A as p,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"适用于所有发行版的 Linux 应用程序——是否真的有好处呢？ | LCTT x X-CMD","titleTemplate":false,"description":"适用于所有发行版的 Linux 应用程序——是否真的有好处呢？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"适用于所有发行版的 Linux 应用程序——是否真的有好处呢？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"适用于所有发行版的 Linux 应用程序——是否真的有好处呢？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good","title":"适用于所有发行版的 Linux 应用程序——是否真的有好处呢？","tag":"201609","desc":""},"relativePath":"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good.md","filePath":"[post].md"}'),d={name:"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good.md"};function g(x,t,T,f,m,w){const o=s("Link");return e(),a("div",null,[t[21]||(t[21]=n("h1",{id:"适用于所有发行版的-linux-应用程序——是否真的有好处呢",tabindex:"-1"},[l("适用于所有发行版的 Linux 应用程序——是否真的有好处呢？ "),n("a",{class:"header-anchor",href:"#适用于所有发行版的-linux-应用程序——是否真的有好处呢","aria-label":"Permalink to “适用于所有发行版的 Linux 应用程序——是否真的有好处呢？”"},"​")],-1)),t[22]||(t[22]=n("p",null,[n("img",{src:"http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/06/Bundled-applications.jpg",alt:""})],-1)),t[23]||(t[23]=n("p",null,"让我们回顾一下 Linux 社区最新的愿景——推动去中心化的应用来解决发行版的碎片化。",-1)),n("p",null,[t[1]||(t[1]=l("继上周的文章：“",-1)),i(o,{href:"https://linux.cn/article-7783-1.html"},{default:p(()=>[...t[0]||(t[0]=[l("Snap、Flatpak 这种通吃所有发行版的打包方式真的有用吗？",-1)])]),_:1}),t[2]||(t[2]=l("” 之后，一系列新观点浮出水面，其中可能包含关于这样应用是否有用的重要信息。",-1))]),t[24]||(t[24]=n("h3",{id:"缺点",tabindex:"-1"},[l("缺点 "),n("a",{class:"header-anchor",href:"#缺点","aria-label":"Permalink to “缺点”"},"​")],-1)),n("p",null,[t[5]||(t[5]=l("就这个话题在",-1)),i(o,{href:"http://www.proli.net/2016/06/25/gnulinux-bundled-application-ramblings/"},{default:p(()=>[...t[3]||(t[3]=[l("这里",-1)])]),_:1}),t[6]||(t[6]=l("的评论，一个叫 Till 的 ",-1)),i(o,{href:"http://www.iwillfolo.com/5-reasons-use-gentoo-linux/"},{default:p(()=>[...t[4]||(t[4]=[l("Gentoo",-1)])]),_:1}),t[7]||(t[7]=l(" 使用者，对于上一次我们未能完全解释的问题给出了一些新的观点。",-1))]),t[25]||(t[25]=u('<p>对于上一次我们选择仅仅称之为膨胀的的东西，Till 从另一方面做了剖析膨胀将来的发展，这可以帮助我们更好的理解它的组成和其影响。</p><p>这些被称之为“捆绑应用”的应用程序能够工作在所有发行版上的机制是——将它依赖的库都包含在它们的应用软件之中，Till 说：</p><blockquote><p>“捆绑应用装载了大量的并不被应用开发者所维护的软件。如果其中的某个函数库被发现了一个安全问题而需要更新的话，你得为每一个独立的应用程序安装更新来确保你的系统安全。”</p></blockquote><p>本质上，Till 提出了一个<strong>重要的安全问题</strong>。但是它并不仅仅与安全有关系，它还关系到许多方面，比如说系统维护、原子更新等等。</p><p>此外，如果我们进一步假设：依赖的开发者们也许会合作，将他们的软件与使用它的应用程序一起发布（一种理想状况），但这将导致整个平台的开发整体放缓。</p><p>另一个将会导致的问题是<strong>透明的依赖关系变得模糊</strong>，就是说，如果你想知道一个应用程序捆绑了哪些依赖关系，你必须依靠开发者发布这些数据。</p><p>或者就像 Till 说的：“比如说像某某包是否已经包含了更新的某函数库这样的问题将会是你每天需要面对的。”</p><p>与之相反，对于 Linux 现行的标准的包管理方法（包括二进制包和源码包），你能够很容易的注意到哪些函数库已经在系统中更新了。</p><p>并且，你也可以很轻松的知道其它哪些应用使用了这个函数库，这就将你从繁琐的单独检查每一个应用程序的工作中解救了出来。</p><p>其他可能由膨胀导致的缺点包括：<strong>更大的包体积</strong>（每一个应用程序捆绑了依赖），<strong>更高的内存占用</strong>（没有共享函数库），并且，<strong>少了一个包过滤机制</strong>来防止恶意软件：发行版的包维护者也充当了一个在开发者和用户之间的过滤者，他保障了用户获得高质量的软件。</p><p>而在捆绑应用中就不再是这种情况了。</p><p>最后一点，Till 声称，尽管在某些情况下很有用，但是在大多数情况下，<strong>捆绑应用程序将弱化自由软件在发行版中的地位</strong>（专有软件供应商将被能够发布他们的软件而不用把它放到公共软件仓库中）。</p><p>除此之外，它引出了许多其他问题。很多问题都可以简单归结到开发人员身上。</p><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><p>相比之下,另一个名叫 Sven 的人的评论试图反驳目前普遍反对使用捆绑应用程序的观点，从而证明和支持使用它。</p><p>“浪费空间？”——Sven 声称在当今世界我们有<strong>很多其他事情在浪费磁盘空间</strong>，比如电影存储在硬盘上、本地安装等等……</p><p>最终，这些事情浪费的空间要远远多于仅仅“ 100 MB 而你每天都要使用的程序。……因此浪费空间的说法实在很荒谬。”</p><p>“浪费运行内存？”——主要的观点有：</p><ul><li><p><strong>共享库浪费的内存要远远少于程序的运行时数据所占用的</strong>。</p></li><li><p>而今运行<strong>内存已经很便宜</strong>了。</p></li></ul><p>“安全梦魇”——不是每个应用程序的运行<strong>真正的要注重安全</strong>。</p><p>而且，<strong>许多应用程序甚至从来没有过任何安全更新</strong>，除非在“滚动更新的发行版”。</p><p>除了 Sven 这种从实用出发的观点以外，Till 其实也指出了捆绑应用在一些情况下也有着其优点：</p><ul><li>专有软件的供应商想要保持他们的代码游离于公共仓库之外将更加容易。</li><li>没有被你的发行版打包进去的小众应用程序将变得更加可行。</li><li>在没有 Beta 包的二进制发行版中测试应用将变得简单。</li><li>将用户从复杂的依赖关系中解放出来。</li></ul><h3 id="最后的思考" tabindex="-1">最后的思考 <a class="header-anchor" href="#最后的思考" aria-label="Permalink to “最后的思考”">​</a></h3><p>虽然关于此问题有着不同的想法，但是有一个被大家共同接受的观点是：<strong>捆绑应用对于填补 Linux 生态系统有着其独到的作用。</strong></p><p>虽然如此，它的定位，不论是主流的还是边缘的，都变得愈发清晰，至少理论上是这样。</p><p>想要尽可能优化其系统的用户，在大多数情况下应该要避免使用捆绑应用。</p><p>而讲究易用性、尽可能在维护系统上少费劲的用户，可能应该会感觉这种新应用十分舒爽。</p><hr>',29)),n("p",null,[t[9]||(t[9]=l("via: ",-1)),i(o,{href:"http://www.iwillfolo.com/linux-applications-that-works-on-all-distributions-are-they-any-good/"},{default:p(()=>[...t[8]||(t[8]=[l("http://www.iwillfolo.com/linux-applications-that-works-on-all-distributions-are-they-any-good/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=l("作者：",-1)),i(o,{href:"http://www.iwillfolo.com/category/editorials/"},{default:p(()=>[...t[10]||(t[10]=[l("Liron",-1)])]),_:1}),t[14]||(t[14]=l(" 译者：",-1)),i(o,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...t[11]||(t[11]=[l("Chao-zhi",-1)])]),_:1}),t[15]||(t[15]=l(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[12]||(t[12]=[l("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=l("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[l("LCTT",-1)])]),_:1}),t[19]||(t[19]=l(" 原创翻译，",-1)),i(o,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[l("Linux中国",-1)])]),_:1}),t[20]||(t[20]=l(" 荣誉推出",-1))])])}const C=r(d,[["render",g]]);export{A as __pageData,C as default};
